(7557069, 1211098, 65234, '<td valign="top">Squee!! OMG, they''re just adorable. Nice diagonal in the composition and detail on the penguins.</td>', 'Squee!! OMG, they''re just adorable. Nice diagonal in the composition and detail on the penguins.', '2018-02-02 11:51:00.000000', NULL, 1),
